</style></head><body><div class="footer">EP Education · Private attendance list · <span class="page">Page </span></div><header><div class="brand"><img src="data:image/png;base64,{{ base64_encode(file_get_contents(public_path('education-landing/ep-logo.png'))) }}" alt="EP">EDUCATION</div><h1>Attendance list</h1><p>{{ count($rows) }} {{ count($rows)===1?'attendee':'attendees' }} · Generated {{ $generated->format('d M Y, h:i A') }} (Asia/Manila)</p><p>@foreach($filters as $key=>$value){{ ucwords(str_replace('_',' ',$key)) }}: {{ $value }}{{ !$loop->last?' · ':'' }}@endforeach @if(!$filters)All schools and events @endif</p></header><table><thead><tr><th style="width:17%">Attendee</th><th style="width:24%">Contact details</th><th style="width:30%">School & event</th><th style="width:13%">Attendance</th><th style="width:16%">RSVP received</th></tr></thead><tbody>@forelse($rows as $row)<tr><td>{{ $row->full_name }}</td><td>{{ $row->email }}<br>{{ $row->phone?:'No contact number' }}</td><td><strong>{{ $row->visit->school }}</strong><br>{{ $row->visit->activity }}<br><span class="muted">{{ $row->visit->summary() }}</span></td><td>{{ $row->attendance_status==='rsvp'?'RSVP':ucfirst($row->attendance_status) }}<br><span class="muted">{{ $row->verified_at?'Email verified':'Email unverified' }}</span></td><td>{{ $row->created_at->timezone('Asia/Manila')->format('d M Y') }}<br>{{ $row->created_at->timezone('Asia/Manila')->format('h:i A') }}</td></tr>@empty<tr><td colspan="5">No attendees match these filters.</td></tr>@endforelse</tbody></table></body></html>
